import random, json
from fractions import Fraction as Fr
R=random.Random(20261017)
out={'g2':[],'g4':[]}
def P(g,q,ask,nums,need,ops,ans,unit,fig,decoy=None,kind=''):
    d=dict(q=q,ask=ask,nums=nums,need=need,ops=ops,ans=ans,unit=unit,fig=fig,kind=kind)
    if decoy is not None:d['decoy']=decoy
    out[g].append(d)
def ev(e):
    e=e.replace('×','*').replace('÷','/');return eval(e)
