# ---------- 検算 ----------
def num(s):
    if isinstance(s,str) and '/' in s:a,b=s.split('/');return Fr(int(a),int(b))
    return Fr(str(s))
def check(p):
    e=p['ops'][0];k=p['kind']
    if k=='がい数': return
    import re
    m=re.match(r'(\d+) ÷ (\d+) の (.*)',e)
    if m:
        a,b=int(m[1]),int(m[2]);q,r=divmod(a,b);v={'{商|しょう}':q,'あまり':r,'{商|しょう} ＋ 1':q+1}[m[3]];assert v==p['ans'],p;return
    ex=re.sub(r'(\d+(?:\.\d+)?(?:/\d+)?)',lambda m:f"num('{m[1]}')",e).replace('×','*').replace('÷','/')
    v=eval(ex);assert abs(float(v)-p['ans'])<1e-9,(p['q'],v,p['ans'])
    for w in p['ops'][1:]:
        if 'の' in w or '→' in w:continue
        ex=re.sub(r'(\d+(?:\.\d+)?(?:/\d+)?)',lambda m:f"num('{m[1]}')",w).replace('×','*').replace('÷','/')
        try:assert abs(float(eval(ex))-p['ans'])>1e-9,('decoy==ans',p['q'],w)
        except ZeroDivisionError:pass
    assert len(set(p['ops']))==3 and len(set(p['ask']))==3,p
for g in out:
    qs=[p['q'] for p in out[g]];assert len(qs)==len(set(qs))
    for p in out[g]:check(p)
import collections
for g in out:print(g,len(out[g]),dict(collections.Counter(p['kind'] for p in out[g])))
